* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #1a2a3a;
  background-image: radial-gradient(#2a4a6a 1px, transparent 1px);
  background-size: 20px 20px;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  padding: 16px;
  color: #e0f0ff;
}

.card {
  background: #0d1b2a;
  border: 4px solid #4a9eff;
  border-radius: 0;
  padding: 32px 24px;
  max-width: 400px;
  width: 100%;
  text-align: center;
  box-shadow: 8px 8px 0 #000;
  image-rendering: pixelated;
}

h1 {
  font-size: 24px;
  margin-bottom: 8px;
  color: #4a9eff;
  letter-spacing: 1px;
}

.subtitle {
  font-size: 16px;
  color: #7a9ab8;
  margin-bottom: 24px;
}

.goal-display {
  font-size: 18px;
  margin-bottom: 16px;
  color: #b8d4f0;
}

.goal-display strong {
  color: #4a9eff;
  font-size: 20px;
}

.progress-container {
  position: relative;
  width: 100%;
  height: 40px;
  background: #1a2a3a;
  border: 3px solid #4a9eff;
  margin-bottom: 24px;
  overflow: hidden;
}

.progress-bar {
  height: 100%;
  width: 0%;
  background: linear-gradient(90deg, #2a6aaa, #4a9eff);
  transition: width 0.2s steps(8);
}

.progress-text {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-size: 16px;
  font-weight: bold;
  color: #fff;
  text-shadow: 1px 1px 0 #000;
  z-index: 1;
}

.controls {
  display: flex;
  gap: 16px;
  justify-content: center;
  margin-bottom: 24px;
  flex-wrap: wrap;
}

.btn {
  font-family: inherit;
  font-size: 18px;
  padding: 12px 24px;
  border: 3px solid;
  border-radius: 0;
  cursor: pointer;
  font-weight: bold;
  letter-spacing: 1px;
  transition: transform 0.05s, background 0.1s;
  min-width: 120px;
  image-rendering: pixelated;
}

.btn-add {
  background: #4a9eff;
  border-color: #2a6aaa;
  color: #fff;
  box-shadow: 4px 4px 0 #000;
}

.btn-add:hover {
  background: #6ab0ff;
}

.btn-add:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 3px;
}

.btn-add:active {
  transform: translate(4px, 4px);
  box-shadow: none;
}

.btn-remove {
  background: #2a4a6a;
  border-color: #1a2a3a;
  color: #b8d4f0;
  box-shadow: 4px 4px 0 #000;
}

.btn-remove:hover {
  background: #3a5a7a;
}

.btn-remove:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 3px;
}

.btn-remove:active {
  transform: translate(4px, 4px);
  box-shadow: none;
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
  box-shadow: 4px 4px 0 #000;
}

.goal-message {
  font-size: 18px;
  font-weight: bold;
  color: #4aff9e;
  min-height: 1.5em;
  margin-bottom: 16px;
  text-shadow: 1px 1px 0 #000;
}

.glasses-visual {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: center;
  min-height: 40px;
}

.glass-icon {
  width: 32px;
  height: 40px;
  background: #1a2a3a;
  border: 3px solid #4a9eff;
  border-top: none;
  position: relative;
  transition: background 0.2s;
}

.glass-icon::before {
  content: '';
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 6px;
  height: 6px;
  background: #4a9eff;
}

.glass-icon.filled {
  background: #4a9eff;
}

.glass-icon.filled::before {
  background: #fff;
}

@media (max-width: 360px) {
  .card {
    padding: 24px 16px;
  }
  .btn {
    min-width: 100px;
    padding: 10px 16px;
    font-size: 16px;
  }
  h1 {
    font-size: 20px;
  }
  .glass-icon {
    width: 24px;
    height: 30px;
  }
}

let glasses = 0;
const goal = 8;

const addBtn = document.getElementById('add-btn');
const removeBtn = document.getElementById('remove-btn');
const progressBar = document.getElementById('progress-bar');
const progressContainer = document.querySelector('.progress-container');
const progressLabel = document.getElementById('progress-label');
const goalMessage = document.getElementById('goal-message');
const glassesVisual = document.getElementById('glasses-visual');
const goalValue = document.getElementById('goal-value');

function updateUI() {
  const percent = Math.min((glasses / goal) * 100, 100);
  progressBar.style.width = percent + '%';
  progressLabel.textContent = glasses + ' / ' + goal;
  progressContainer.setAttribute('aria-valuenow', glasses);
  progressContainer.setAttribute('aria-valuemax', goal);

  if (glasses >= goal) {
    goalMessage.textContent = '🎉 Goal reached! Great job staying hydrated!';
  } else {
    goalMessage.textContent = '';
  }

  removeBtn.disabled = glasses <= 0;

  glassesVisual.innerHTML = '';
  for (let i = 0; i < goal; i++) {
    const icon = document.createElement('div');
    icon.className = 'glass-icon' + (i < glasses ? ' filled' : '');
    glassesVisual.appendChild(icon);
  }
}

addBtn.addEventListener('click', () => {
  if (glasses < goal) {
    glasses++;
    updateUI();
  }
});

removeBtn.addEventListener('click', () => {
  if (glasses > 0) {
    glasses--;
    updateUI();
  }
});

// Initialize
goalValue.textContent = goal;
updateUI();
